<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionThemeVO;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionChannelVO;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionChannelOptions;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionLocaleVO;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionContentHtmlVO;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionContentTextVO;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionVersionVO;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionAttributes;
use PHPUnit\Framework\TestCase;

final class ThemeVersionAttributesUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new ThemeVersionAttributes();
        $themeOneValue = new ThemeRef('one');
        $themeOtherValue = new ThemeRef('other');
        $copy = $value->theme($themeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new ThemeRef('one'), $value->getTheme());
        $this->assertNotEquals(new ThemeRef('other'), $value->getTheme());
        $this->assertEquals(new ThemeRef('one'), $value->getThemeOrCurrent(ThemeVersionThemeVO::from($themeOtherValue))->value());
        $this->assertNotEquals(new ThemeRef('other'), $value->getThemeOrCurrent(ThemeVersionThemeVO::from($themeOtherValue))->value());
        $value->unsetTheme();
        $this->assertEquals(new ThemeRef('other'), $value->getThemeOrCurrent(ThemeVersionThemeVO::from($themeOtherValue))->value());
        $this->assertNotEquals(new ThemeRef('one'), $value->getThemeOrCurrent(ThemeVersionThemeVO::from($themeOtherValue))->value());
        $channelOneValue = ThemeVersionChannelOptions::MAIL;
        $channelOtherValue = ThemeVersionChannelOptions::HTML;
        $copy = $value->channel($channelOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(ThemeVersionChannelOptions::MAIL, $value->getChannel());
        $this->assertNotEquals(ThemeVersionChannelOptions::HTML, $value->getChannel());
        $this->assertEquals(ThemeVersionChannelOptions::MAIL, $value->getChannelOrCurrent(ThemeVersionChannelVO::from($channelOtherValue))->value());
        $this->assertNotEquals(ThemeVersionChannelOptions::HTML, $value->getChannelOrCurrent(ThemeVersionChannelVO::from($channelOtherValue))->value());
        $value->unsetChannel();
        $this->assertEquals(ThemeVersionChannelOptions::HTML, $value->getChannelOrCurrent(ThemeVersionChannelVO::from($channelOtherValue))->value());
        $this->assertNotEquals(ThemeVersionChannelOptions::MAIL, $value->getChannelOrCurrent(ThemeVersionChannelVO::from($channelOtherValue))->value());
        $localeOneValue = 'one';
        $localeOtherValue = 'other';
        $copy = $value->locale($localeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getLocale());
        $this->assertNotEquals('other', $value->getLocale());
        $this->assertEquals('one', $value->getLocaleOrCurrent(ThemeVersionLocaleVO::from($localeOtherValue))->value());
        $this->assertNotEquals('other', $value->getLocaleOrCurrent(ThemeVersionLocaleVO::from($localeOtherValue))->value());
        $value->unsetLocale();
        $this->assertEquals('other', $value->getLocaleOrCurrent(ThemeVersionLocaleVO::from($localeOtherValue))->value());
        $this->assertNotEquals('one', $value->getLocaleOrCurrent(ThemeVersionLocaleVO::from($localeOtherValue))->value());
        $contentHtmlOneValue = 'one';
        $contentHtmlOtherValue = 'other';
        $copy = $value->contentHtml($contentHtmlOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getContentHtml());
        $this->assertNotEquals('other', $value->getContentHtml());
        $this->assertEquals('one', $value->getContentHtmlOrCurrent(ThemeVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $this->assertNotEquals('other', $value->getContentHtmlOrCurrent(ThemeVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $value->unsetContentHtml();
        $this->assertEquals('other', $value->getContentHtmlOrCurrent(ThemeVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $this->assertNotEquals('one', $value->getContentHtmlOrCurrent(ThemeVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $contentTextOneValue = 'one';
        $contentTextOtherValue = 'other';
        $copy = $value->contentText($contentTextOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getContentText());
        $this->assertNotEquals('other', $value->getContentText());
        $this->assertEquals('one', $value->getContentTextOrCurrent(ThemeVersionContentTextVO::from($contentTextOtherValue))->value());
        $this->assertNotEquals('other', $value->getContentTextOrCurrent(ThemeVersionContentTextVO::from($contentTextOtherValue))->value());
        $value->unsetContentText();
        $this->assertEquals('other', $value->getContentTextOrCurrent(ThemeVersionContentTextVO::from($contentTextOtherValue))->value());
        $this->assertNotEquals('one', $value->getContentTextOrCurrent(ThemeVersionContentTextVO::from($contentTextOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(ThemeVersionVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(ThemeVersionVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(ThemeVersionVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(ThemeVersionVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
